            targets[i] = ToNative(v.Targets[i], arena);
        }

        return new WGPUFragmentState
        {
            Module = v.Module.Handle,
            EntryPoint = arena.String(v.EntryPoint),
            ConstantCount = (nuint)v.Constants.Length,
            Constants = constants,
            TargetCount = (nuint)v.Targets.Length,
            Targets = targets,
        };
    }

